import{_ as s,o as e,c as o,a4 as a}from"./chunks/framework.B-wJupoK.js";const r="/assets/image-20260717182040006.ALF1UbYj.webp",t="/assets/image-20260717182106561.B4cPBjPL.webp",i="/assets/image-20260717182222246.3c9wSoTW.webp",d="/assets/image-20260717182239325.DGz3Lh1p.webp",l="/assets/image-20260717182250393.DbEwPbw8.webp",c="/assets/image-20260717182307971.CacrDH-x.webp",p="/assets/image-20260717182329442.vZpRUbc5.webp",_="/assets/image-20260717181909378.h1eCCnKt.webp",B=JSON.parse('{"title":"用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃/用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃.md","filePath":"AI人工智能/用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃/用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃.md","lastUpdated":1784284218000,"__rawMarkdown":"# 用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃\\n\\n\\n\\n## 天天用的界面，能不能好看一点？\\n\\nWorkBuddy 是一款很趁手的桌面工具，但默认界面看久了难免有点单调。作为一个既想要颜值、又不敢乱改软件的人，我做了一个小工具——**workbuddy-skin**，给它换上背景壁纸和毛玻璃质感的界面，而且**全程不碰任何官方文件**，随时能变回原样。\\n\\n现在它已经打包成**双击就能用的绿色程序**，不用装环境、不用敲命令，普通用户也能轻松上手。\\n\\n\\n\\n![](assets/image-20260717182040006.webp)\\n\\n---\\n\\n![](assets/image-20260717182106561.webp)\\n\\n---\\n\\n![](assets/image-20260717182222246.webp)\\n\\n---\\n\\n![](assets/image-20260717182239325.webp)\\n\\n---\\n\\n![](assets/image-20260717182250393.webp)\\n\\n---\\n\\n![](assets/image-20260717182307971.webp)\\n\\n---\\n\\n![image-20260717182329442](assets/image-20260717182329442.webp)\\n\\n## 它做了什么\\n\\n- **真背景层**：在整个窗口铺一张连续壁纸（内置渐变主题，也可换成你自己的照片）。\\n- **玻璃界面**：侧边栏、顶栏、菜单栏、卡片、输入框统统变成半透明毛玻璃，透出背景。\\n- **自动主题色**：换壁纸时自动提取封面主色，给玻璃描边和高光上色，让界面和背景更搭。\\n- **明暗自适应**：跟随 WorkBuddy 的浅色 / 暗色主题自动切换配色。\\n- **多主题一键切换**：内置 5 套预设（极光玻璃 / 午夜蓝 / 樱 / 石墨 / 立绘应援），可实时切换，不用重启。\\n- **可还原**：一条操作移除皮肤、干净重启，恢复官方原样。\\n\\n界面里的侧栏、卡片、输入框都是 WorkBuddy 的**原生控件**，不是贴图，点击照常好用。\\n\\n## 怎么用\\n\\n1. 打开项目的 **Releases** 页面，下载对应你系统的文件：\\n   - Windows：`workbuddy-skin-windows-x64.exe`\\n   - macOS（Apple 芯片）：`workbuddy-skin-macos-arm64`\\n   - macOS（Intel）：`workbuddy-skin-macos-x64`\\n   - Linux：`workbuddy-skin-linux-x64`\\n2. **双击运行**，弹出一个中文菜单。\\n3. 按数字选择即可：\\n   - `1` 应用皮肤（自动启动 WorkBuddy 并换肤）\\n   - `2` 选择主题\\n   - `3` 设置壁纸（把图片拖进窗口或粘贴路径）\\n   - `5` 还原为官方外观\\n\\n单个程序已内置全部主题与样式资源，**离线可用、绿色免安装**，删除文件即卸载。\\n\\n### \\n\\n![](assets/image-20260717181909378.webp)\\n\\n\\n\\n## 如何获取\\n\\n如果国内下载慢的话，可以通过私信 “workbuddy 皮肤”，获取国内下载地址。\\n\\n\\n\\n"}'),u={name:"AI人工智能/用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃/用腻了 WorkBuddy 的默认界面？这个开源小工具给它换上了毛玻璃.md"};function m(g,n,k,b,w,h){return e(),o("div",null,[...n[0]||(n[0]=[a("",27)])])}const x=s(u,[["render",m]]);export{B as __pageData,x as default};
